import XCTest
@testable import WhiskyKit

final class JavaGameTunerTests: XCTestCase {
    func testDetectsJavaExecutableNames() {
        let url = URL(fileURLWithPath: "/bottle/drive_c/java/javaw.exe")
        XCTAssertEqual(
            JavaGameTuner.detect(executable: url, importProfile: nil, args: []),
            .executableName
        )
    }

    func testDetectsJarFromCommandLine() {
        let url = URL(fileURLWithPath: "/bottle/drive_c/game/Launcher.exe")
        XCTAssertEqual(
            JavaGameTuner.detect(
                executable: url,
                importProfile: nil,
                args: ["-jar", "minecraft.jar"]
            ),
            .commandLine
        )
    }

    func testDetectsJvmDllImport() throws {
        let url = try makeImage(withImport: "jvm.dll")
        let profile = PEImportScanner.scan(url: url)
        XCTAssertEqual(
            JavaGameTuner.detect(
                executable: URL(fileURLWithPath: "/bottle/drive_c/Launcher.exe"),
                importProfile: profile,
                args: []
            ),
            .peImport
        )
        try? FileManager.default.removeItem(at: url)
    }

    func testUndetectedForOrdinaryGame() {
        let url = URL(fileURLWithPath: "/bottle/drive_c/game/Game.exe")
        XCTAssertEqual(
            JavaGameTuner.detect(executable: url, importProfile: nil, args: ["-windowed"]),
            .none
        )
    }

    func testHeapScalesWithMemoryAndClamps() {
        // Quarter of RAM clamped to [2, 8] GB (decimal megabytes).
        XCTAssertEqual(JavaGameTuner.recommendedHeapMegabytes(physicalMemoryBytes: 8_000_000_000), 2048)
        XCTAssertEqual(JavaGameTuner.recommendedHeapMegabytes(physicalMemoryBytes: 16_000_000_000), 4000)
        XCTAssertEqual(JavaGameTuner.recommendedHeapMegabytes(physicalMemoryBytes: 128_000_000_000), 4096)
        XCTAssertEqual(JavaGameTuner.recommendedHeapMegabytes(physicalMemoryBytes: 4_000_000_000), 2048)
    }

    func testRecommendedTargetCapsEveryPool() {
        let target = JavaGameTuner.recommendedJVMTarget(heapMegabytes: 4096)
        // Heap grows into the workload instead of pre-committing.
        XCTAssertTrue(target.contains("-Xms512M"))
        XCTAssertTrue(target.contains("-Xmx4096M"))
        XCTAssertTrue(target.contains("-XX:+UseG1GC"))
        XCTAssertTrue(target.contains("-XX:MaxGCPauseMillis=40"))
        // Every non-heap pool has a hard ceiling.
        XCTAssertTrue(target.contains("-XX:ReservedCodeCacheSize=128m"))
        XCTAssertTrue(target.contains("-XX:MaxMetaspaceSize=256m"))
        XCTAssertTrue(target.contains("-XX:MaxDirectMemorySize=256M"))
        // Idle reclamation shrinks committed heap back down.
        XCTAssertTrue(target.contains("-XX:G1PeriodicGCInterval=15000"))
    }

    func testUserJavaOptionsArePreservedVerbatim() {
        let posture = JavaGameTuner.environmentPosture(
            existingJavaOptions: "-Xmx2G -XX:+UseZGC",
            heapMegabytes: 4096
        )
        XCTAssertEqual(posture["_JAVA_OPTIONS"], "-Xmx2G -XX:+UseZGC")
    }

    func testPostureProvidesFullTargetWhenUserSilent() {
        let posture = JavaGameTuner.environmentPosture(
            existingJavaOptions: nil,
            heapMegabytes: 4096
        )
        let options = posture["_JAVA_OPTIONS"] ?? ""
        XCTAssertTrue(options.contains("-Xmx4096M"))
        XCTAssertTrue(options.contains("-Xms512M"))
        XCTAssertTrue(options.contains("MaxGCPauseMillis=40"))
        XCTAssertTrue(options.contains("MaxDirectMemorySize=256M"))
    }

    private func makeImage(withImport dll: String) throws -> URL {
        // Byte-exact PE32+ template (same ground truth as
        // PEImportScannerTests) with the import DLL name patched.
        // swiftlint:disable:next line_length
        let referenceHex = ""
        var data = Data()
        var index = referenceHex.startIndex
        while index < referenceHex.endIndex {
            let next = referenceHex.index(index, offsetBy: 2)
            guard let byte = UInt8(referenceHex[index..<next], radix: 16) else {
                XCTFail("invalid hex fixture")
                return URL(fileURLWithPath: "/dev/null")
            }
            data.append(byte)
            index = next
        }
        let name = Array(dll.lowercased().utf8) + [0]
        data.replaceSubrange(0x2200..<0x2200 + name.count, with: Data(name))
        let url = FileManager.default.temporaryDirectory
            .appending(component: "pe-jvm-\(UUID().uuidString).exe")
        try data.write(to: url)
        PEImportScanner.invalidateCache(for: url)
        return url
    }
}
